### **3. JavaScript (`script.js`)**

```javascript
const canvas = document.getElementById('imageCanvas');
const ctx = canvas.getContext('2d');

let image = null; // Loaded image object
let isImageLoaded = false;
let uploadEnabled = true; // Controls whether clicking opens file dialog

// Create a hidden file input for click-to-upload
const fileInput = document.createElement('input');
fileInput.type = 'file';
fileInput.accept = 'image/*';

// Resize canvas to fill window
function resizeCanvas() {
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;
    draw(); // Redraw on resize
}

// Draw function to display message or image
function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    if (!isImageLoaded) {
        // Draw background
        ctx.fillStyle = '#222';
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        // Draw message
        ctx.fillStyle = '#fff';
        ctx.font = '24px Arial';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('Drop an image here or click to upload', canvas.width / 2, canvas.height / 2);
    } else {
        // Draw the image cropped to fit the canvas
        drawImageCrop();
    }
}

// Function to draw the image cropped to fit the canvas
function drawImageCrop() {
    const canvasAspect = canvas.width / canvas.height;
    const imgAspect = image.width / image.height;

    let drawWidth, drawHeight, offsetX, offsetY;

    if (imgAspect > canvasAspect) {
        // Image is wider than canvas
        drawHeight = canvas.height;
        drawWidth = image.width * (canvas.height / image.height);
        offsetX = (canvas.width - drawWidth) / 2;
        offsetY = 0;
    } else {
        // Image is taller than canvas
        drawWidth = canvas.width;
        drawHeight = image.height * (canvas.width / image.width);
        offsetX = 0;
        offsetY = (canvas.height - drawHeight) / 2;
    }

    ctx.drawImage(image, offsetX, offsetY, drawWidth, drawHeight);
}

// Handle window resize
window.addEventListener('resize', resizeCanvas);

// Initialize canvas size
resizeCanvas();

// Handle click for upload (only if upload is enabled)
canvas.addEventListener('click', () => {
    if (uploadEnabled) {
        fileInput.click();
    }
});

// Handle file input change
fileInput.addEventListener('change', (e) => {
    const file = e.target.files[0];
    if (file && file.type.startsWith('image/')) {
        loadImageFromFile(file);
    }
});

// Drag and Drop events
canvas.addEventListener('dragover', (e) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'copy';
});

canvas.addEventListener('drop', (e) => {
    e.preventDefault();
    const file = e.dataTransfer.files[0];
    if (file && file.type.startsWith('image/')) {
        loadImageFromFile(file);
    }
});

// Function to load image from file
function loadImageFromFile(file) {
    const reader = new FileReader();
    reader.onload = function(event) {
        const img = new Image();
        img.onload = () => {
            image = img;
            isImageLoaded = true;
            // Disable click-to-upload after image is loaded
            uploadEnabled = false;
            draw();
        };
        img.src = event.target.result;
    };
    reader.readAsDataURL(file);
}

// Optional: Allow user to reset and upload a new image by clicking again
// Uncomment the following if you want to enable re-uploading:

/*
canvas.addEventListener('click', () => {
    if (!isImageLoaded) {
        fileInput.click();
    } else {
        // To re-upload, uncomment below:
        // isImageLoaded = false;
        // image = null;
        // uploadEnabled = true;
        // draw();
    }
});
*/

// Initial draw
draw();
```

---

### **Summary of Features:**

- The canvas fills the entire viewport.
- Initially, it displays a message: "Drop an image here or click to upload".
- Clicking on the canvas opens a file dialog to select an image.
- Dragging and dropping images onto the canvas loads them.
- Once an image is loaded, clicking to upload is disabled.
- The image is displayed cropped to fit the canvas, maintaining aspect ratio.

